// Paperless-IDs (Instanz web-wikinger): Custom Fields und Select-Optionen
const CF = { rechnungsnummer: 1, zahlart: 2, firma: 3, brutto: 6, netto: 7, rechnungstyp: 8 };
const ZAHLART = { Rechnung: '9fyH21EOJWI8l7GF', Vorkasse: 'SlDzw9DHxVOmDnJD', Kreditkarte: 'hMSLnG9gG8elm97q',
                  Abo: 'L9U1lgDZsXvBnXqX', Lastschrift: 'vSSit6JyEqdBW4PJ', Paypal: 'jzEwRWEh7YPnA22y' };
const TYP = { Rechnung: '2b3JjQz0283yqzpB', Gutschrift: 'aS36nmVB2iRUY9U2', Stornorechnung: 'zTKbB4kUcRU95nKR' };
const TAG_GEPRUEFT = Number('KI_GEPRUEFT_TAG_ID');   // ID des Tags "KI-geprüft" eintragen
const MIN_SICHERHEIT = 0.8;                          // darunter: nur Tag + Notiz, keine Feldänderung

const out = [];
for (const [i, item] of $input.all().entries()) {
  const doc = $('Dokumente einzeln').all()[i].json;
  const ki = item.json.output || {};
  const felder = Object.fromEntries((doc.custom_fields || []).map(f => [f.field, f.value]));
  const vorher = { ...felder };
  const geld = (b) => (b == null ? null : `${(ki.waehrung || 'EUR').toUpperCase()}${Number(b).toFixed(2)}`);
  const soll = {
    [CF.rechnungsnummer]: ki.rechnungsnummer || null,
    [CF.firma]: ki.firma || null,
    [CF.brutto]: geld(ki.brutto),
    [CF.netto]: geld(ki.netto),
    [CF.zahlart]: ZAHLART[ki.zahlart] || null,
    [CF.rechnungstyp]: TYP[ki.rechnungstyp] || null,
  };
  const aenderungen = [];
  if ((ki.sicherheit ?? 0) >= MIN_SICHERHEIT) {
    for (const [fid, wert] of Object.entries(soll)) {
      if (wert != null && felder[fid] !== wert) {          // SevdeskID/Kundennummer werden nie angefasst
        aenderungen.push(`Feld ${fid}: ${felder[fid] ?? '–'} → ${wert}`);
        felder[fid] = wert;
      }
    }
  }
  const tags = [...new Set([...(doc.tags || []), TAG_GEPRUEFT])];
  out.push({ json: {
    id: doc.id,
    patch: { custom_fields: Object.entries(felder).map(([field, value]) => ({ field: Number(field), value })), tags },
    notiz: `KI-Prüfung (Gemini, Sicherheit ${ki.sicherheit ?? '?'}): ${ki.pruefhinweis || ''}` +
           (aenderungen.length ? `\nGeändert: ${aenderungen.join('; ')}` : '\nKeine Feldänderung.') +
           (ki.ist_zahlungsbeleg ? '\nHinweis: Zahlungsbeleg, keine Rechnung.' : '') +
           `\nVorher: ${JSON.stringify(vorher)}`,
  }});
}
return out;
